import {
    BooleanColumn,
    GenericColumn,
    IntegerColumn,
    StringColumn,
    Table,
    TranslatedFieldColumn,
    UserRolesColumn,
} from '../../db'

export const item_option_new_set = Table({
    name: 'item_option_new_set',
    extends: 'sys_metadata',
    schema: {
        create_roles: UserRolesColumn({ mandatory: false, label: 'Create roles', read_only: false, active: true }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 4000,
            dropdown: 'none',
        }),
        display_title: BooleanColumn({
            mandatory: false,
            label: 'Display title',
            read_only: false,
            active: true,
            default: false,
        }),
        internal_name: StringColumn({
            mandatory: true,
            label: 'Internal name',
            read_only: false,
            active: true,
            maxLength: 80,
            dropdown: 'none',
        }),
        layout: StringColumn({
            mandatory: false,
            label: 'Layout',
            read_only: false,
            active: true,
            default: 'normal',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
        }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        order: IntegerColumn({ mandatory: false, label: 'Order', read_only: false, active: true, default: 100 }),
        read_roles: UserRolesColumn({ mandatory: false, label: 'Read roles', read_only: false, active: true }),
        set_attributes: StringColumn({
            mandatory: false,
            label: 'Variable Set attributes',
            read_only: false,
            active: true,
            maxLength: 255,
            dropdown: 'none',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        title: TranslatedFieldColumn({ mandatory: true, label: 'Title', read_only: false, active: true }),
        type: StringColumn({
            mandatory: false,
            label: 'Type',
            read_only: true,
            active: true,
            default: 'one_to_one',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                one_to_one: { label: 'Single Row', sequence: 100, inactive: false, language: 'en' },
                one_to_many: { label: 'Multi Row', sequence: 200, inactive: false, language: 'en' },
            },
        }),
        version: IntegerColumn({ mandatory: false, label: 'Version', read_only: true, active: true }),
        write_roles: UserRolesColumn({ mandatory: false, label: 'Write roles', read_only: false, active: true }),
    },
})
